func exportData() {
    do {
        let data = try JSONEncoder().encode(taskStore.tasks)

        // 获取"我的iPhone/乘风计划"目录
        let documentsURL = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
        let appFolder = documentsURL.appendingPathComponent("乘风计划", isDirectory: true)

        // 自动创建文件夹
        try FileManager.default.createDirectory(at: appFolder, withIntermediateDirectories: true)

        let fileName = "backup_\(Date().formatted(.iso8601)).json"
        let fileURL = appFolder.appendingPathComponent(fileName)

        try data.write(to: fileURL)

        // ✅ 使用 fileExporter 让用户确认保存位置
        exportFileURL = fileURL
        showExporter = true

        showToast("✅ 导出成功：\(fileName)")
    } catch {
        showToast("❌ 导出失败：\(error.localizedDescription)")
    }
}

// View 中绑定
.fileExporter(isPresented: $showExporter, item: exportFileURL, contentType: .json) { result in
    switch result {
    case .success(let url):
        showToast("✅ 已保存到：\(url.lastPathComponent)")
    case .failure(let error):
        showToast("❌ 保存取消或失败：\(error.localizedDescription)")
    }
}
