struct ExportPackage {
    let metadata: ExportMetadata
    let tasks: [Task]
    let aiInteractions: [AIInteraction]
    let analyticsSummaries: [AnalyticsSummary]

    func generate() async throws -> URL {
        let tempDir = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: tempDir, withIntermediateDirectories: true)

        // 1. Markdown主文件（人类可读）
        let markdown = generateMarkdown(tasks: tasks, interactions: aiInteractions)
        try markdown.write(to: tempDir.appendingPathComponent("chengfeng_export.md"), atomically: true, encoding: .utf8)

        // 2. JSON-LD元数据（机器可读）
        let jsonLD = generateJSONLD(metadata: metadata, tasks: tasks)
        try JSONEncoder().encode(jsonLD).write(to: tempDir.appendingPathComponent("metadata.jsonld"))

        // 3. 导入脚本模板
        try copyImportScripts(to: tempDir)

        return tempDir
    }
}

