// AppSettingsStore.swift - 集中式类型安全配置
@Observable
final class AppSettingsStore {
    // 外观
    @AppStorage("appTheme") var theme: AppTheme = .system
    // 数据
    @AppStorage("defaultPriority") var defaultPriority: Priority = .medium
    @AppStorage("weekStartDay") var weekStartDay: Weekday = .monday
    // AI
    @AppStorage("aiModelTier") var aiModelTier: AIModelTier = .local
    @AppStorage("aiSensitivity") var aiSensitivity: AISensitivity = .medium
    // 隐私
    @AppStorage("hideContentOnLockScreen") var hideContentOnLockScreen = false

    // 变更审计
    func update<T>(_ keyPath: WritableKeyPath<AppSettingsStore, T>, value: T) where T: Equatable {
        let oldValue = self[keyPath: keyPath]
        guard oldValue != value else { return }
        self[keyPath: keyPath] = value
        SettingsAuditLogger.log(key: String(describing: keyPath), old: oldValue, new: value)
    }
}

